import{_ as r,o as t,c as o,a2 as l}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"鹤族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/鹤族.md","filePath":"表层/种族/鹤族.md","lastUpdated":1787065118000}'),e={name:"表层/种族/鹤族.md"};function i(n,a,s,h,g,d){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="鹤族" tabindex="-1">鹤族 <a class="header-anchor" href="#鹤族" aria-label="Permalink to &quot;鹤族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>鹤族是五大主族之一，共同体时期承担政治相关的一切，以<strong>总体思考与大局观</strong>为种族核心特质。然而，由于神明掌握实权，鹤族长期仅承担传递神明信息与基层管理工作，缺乏顶层策略制定的实践经验，执政威信不足。共同体解体后鹤族隐居山林，族群规模极小，不再参与大陆政治事务。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，有喙，下肢为爪形，双翅结构向手臂靠拢，末端有功能完善的手。</li><li><strong>羽毛配色</strong>：白色为主，黑色为辅。</li><li><strong>体格</strong>：整体瘦高，体质在羽族中最为弱小。</li><li><strong>翅膀结构</strong>：拥有完整的翅膀结构，具备飞行能力。在羽族中，鹤族的飞行高度与耐力最佳。</li><li><strong>骨骼</strong>：骨骼轻盈但强度极高，属羽族共同特征。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-总体思考与大局观" tabindex="-1">核心特质：总体思考与大局观 <a class="header-anchor" href="#核心特质-总体思考与大局观" aria-label="Permalink to &quot;核心特质：总体思考与大局观&quot;">​</a></h3><ul><li><strong>全局思维</strong>：天生擅长从全局角度思考问题，注重整体而非局部。</li><li><strong>战略规划</strong>：具备长远的战略规划能力，能够跨越时间维度审视决策的后果。</li><li><strong>平衡考量</strong>：善于在不同利益之间寻求平衡。</li></ul><h3 id="性格特征" tabindex="-1">性格特征 <a class="header-anchor" href="#性格特征" aria-label="Permalink to &quot;性格特征&quot;">​</a></h3><ul><li><strong>审慎</strong>：决策前会进行充分思考，不易冲动。</li><li><strong>周全</strong>：考虑问题周全，注重细节与整体关系。</li><li><strong>公正</strong>：追求公正和平衡的解决方案。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="共同体时期-政治担当" tabindex="-1">共同体时期：政治担当 <a class="header-anchor" href="#共同体时期-政治担当" aria-label="Permalink to &quot;共同体时期：政治担当&quot;">​</a></h3><p>在五大主族分工的共同体体系中，鹤族承担<strong>政治相关的一切</strong>，在共同体五星旗帜上占据一角。</p><p>然而，在神明掌握实权的情况下，鹤族实际上<strong>仅负责传递神明信息与基层管理工作</strong>，严重缺乏顶层策略制定的实践经验：</p><ul><li><strong>威信不足</strong>：虽有理论知识，但缺乏顶层实践经验。地脉灾难前，神明将部分管理权力移交鹤族后，民众普遍抱怨&quot;鹤族的管理远不如神明&quot;。</li><li><strong>决策瘫痪</strong>：高层决策因无法服众而陷入停滞，只能等待神明回归处理，社会问题逐渐积压。</li></ul><h3 id="共同体末期-被架空" tabindex="-1">共同体末期：被架空 <a class="header-anchor" href="#共同体末期-被架空" aria-label="Permalink to &quot;共同体末期：被架空&quot;">​</a></h3><p>共同体末期，鹿族作为主族之首独揽大权，主导&quot;神明复活计划&quot;。该计划发生严重事故，引发第二次地脉灾难，甲族损失惨重，共同体基础设施几近崩断。事故后政权重组为鹿、熊、牛、甲四族平级，<strong>鹤族继续被架空</strong>，被彻底排除出权力核心。此后鹰族逐渐从底层崛起，掌握舆论话语权，鹤族进一步边缘化。</p><h3 id="退出舞台-隐居山林" tabindex="-1">退出舞台：隐居山林 <a class="header-anchor" href="#退出舞台-隐居山林" aria-label="Permalink to &quot;退出舞台：隐居山林&quot;">​</a></h3><p>共同体解体后，鹤族已完全丧失话语权，选择<strong>隐居山林</strong>，从此不再参与大陆政治事务，成为第一个退出历史舞台的五大主族。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><ul><li><strong>居住地</strong>：隐居山林，远离主要文明区域。</li><li><strong>族群规模</strong>：<strong>极小</strong>，人口数量极低，处于种族存续的边缘状态。</li><li><strong>生活方式</strong>：以极其低调的方式维持种族存在，形成了独特的避世文化。</li><li><strong>传承之物</strong>：保存了共同体时期的部分历史记录与政治知识，但因脱离实践日久，已逐渐教条化。</li></ul><hr><h2 id="与其余种族的关系" tabindex="-1">与其余种族的关系 <a class="header-anchor" href="#与其余种族的关系" aria-label="Permalink to &quot;与其余种族的关系&quot;">​</a></h2><ul><li><strong>与鹿族</strong>：曾被鹿族夺权架空。鹿族在神明退场后以鹤族&quot;公信力不足&quot;为由独揽大权，是鹤族政治边缘化的直接推手。详见 <a href="./鹿族">鹿族</a>。</li><li><strong>与兔族</strong>：同为隐居种族，当前与兔族<strong>联系紧密</strong>。详见 <a href="./兔族">兔族</a>。</li><li><strong>与牛族</strong>：同为隐居种族，共同体时期分别承担农业与政治事务。详见 <a href="./牛族">牛族</a>。</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./五大主族总览">五大主族总览</a></li><li><a href="./../历史/共同体时期">共同体时期</a></li><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./鹿族">鹿族</a></li><li><a href="./兔族">兔族</a></li><li><a href="./牛族">牛族</a></li></ul><hr>',32)])])}const q=r(e,[["render",i]]);export{c as __pageData,q as default};
